<?php
require dirname(__DIR__) . '/config.php'; require_login(); update_overdue($pdo);
$page = $_GET['page'] ?? 'dashboard';
$allowed = ['dashboard','books','categories','members','issues','return','overdue','reports','users'];
if (!in_array($page,$allowed,true)) $page='dashboard';

if (is_post()) {
  verify_csrf(); $action=$_POST['action']??'';
  try {
    if ($action==='save_book') {
      $id=(int)($_POST['id']??0); $qty=max(0,(int)$_POST['quantity']);
      if($id){$old=$pdo->prepare('SELECT quantity,available_quantity FROM books WHERE id=?');$old->execute([$id]);$b=$old->fetch();$issued=$b['quantity']-$b['available_quantity'];$avail=max(0,$qty-$issued);$pdo->prepare('UPDATE books SET isbn=?,title=?,author=?,category_id=?,publisher=?,quantity=?,available_quantity=? WHERE id=?')->execute([trim($_POST['isbn']),trim($_POST['title']),trim($_POST['author']),$_POST['category_id']?:null,trim($_POST['publisher']),$qty,$avail,$id]);}
      else{$pdo->prepare('INSERT INTO books(isbn,title,author,category_id,publisher,quantity,available_quantity) VALUES(?,?,?,?,?,?,?)')->execute([trim($_POST['isbn']),trim($_POST['title']),trim($_POST['author']),$_POST['category_id']?:null,trim($_POST['publisher']),$qty,$qty]);} flash('success','Book saved successfully.');
    } elseif($action==='delete_book') {$pdo->prepare('DELETE FROM books WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Book deleted.');}
    elseif($action==='save_category') {$id=(int)($_POST['id']??0);if($id)$pdo->prepare('UPDATE categories SET category_name=?,description=? WHERE id=?')->execute([trim($_POST['category_name']),trim($_POST['description']),$id]);else $pdo->prepare('INSERT INTO categories(category_name,description) VALUES(?,?)')->execute([trim($_POST['category_name']),trim($_POST['description'])]);flash('success','Category saved.');}
    elseif($action==='delete_category') {$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Category deleted.');}
    elseif($action==='save_member') {$id=(int)($_POST['id']??0);$v=[trim($_POST['member_no']),trim($_POST['full_name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['address'])];if($id){$v[]=$id;$pdo->prepare('UPDATE members SET member_no=?,full_name=?,email=?,phone=?,address=? WHERE id=?')->execute($v);}else $pdo->prepare('INSERT INTO members(member_no,full_name,email,phone,address) VALUES(?,?,?,?,?)')->execute($v);flash('success','Member saved.');}
    elseif($action==='delete_member') {$pdo->prepare('DELETE FROM members WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Member deleted.');}
    elseif($action==='save_user') {
      $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'member';$status=$_POST['status']??'active';$password=$_POST['password']??'';
      if(!in_array($role,['admin','librarian','member'],true)||!in_array($status,['active','inactive','suspended'],true)||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('Please enter valid user details.');
      if($id){if($password!=='')$pdo->prepare('UPDATE users SET name=?,email=?,role=?,status=?,password=? WHERE id=?')->execute([$name,$email,$role,$status,password_hash($password,PASSWORD_DEFAULT),$id]);else $pdo->prepare('UPDATE users SET name=?,email=?,role=?,status=? WHERE id=?')->execute([$name,$email,$role,$status,$id]);}
      else{if(strlen($password)<6)throw new Exception('Password must contain at least 6 characters.');$pdo->prepare('INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$status]);}flash('success','User saved successfully.');
    }
    elseif($action==='delete_user') {if((int)$_POST['id']===(int)$_SESSION['user']['id'])throw new Exception('You cannot delete your own account.');$pdo->prepare('DELETE FROM users WHERE id=?')->execute([(int)$_POST['id']]);flash('success','User deleted.');}
    elseif($action==='issue_book') {$pdo->beginTransaction();$book=$pdo->prepare('SELECT available_quantity FROM books WHERE id=? FOR UPDATE');$book->execute([(int)$_POST['book_id']]);if((int)$book->fetchColumn()<1)throw new Exception('Selected book is not available.');$pdo->prepare("INSERT INTO book_issues(member_id,book_id,issue_date,due_date,status) VALUES(?,?,?,?,'issued')")->execute([(int)$_POST['member_id'],(int)$_POST['book_id'],$_POST['issue_date'],$_POST['due_date']]);$pdo->prepare('UPDATE books SET available_quantity=available_quantity-1 WHERE id=?')->execute([(int)$_POST['book_id']]);$pdo->commit();flash('success','Book issued successfully.');}
    elseif($action==='return_book') {$pdo->beginTransaction();$q=$pdo->prepare('SELECT book_id,due_date FROM book_issues WHERE id=? AND return_date IS NULL FOR UPDATE');$q->execute([(int)$_POST['id']]);$issue=$q->fetch();if(!$issue)throw new Exception('Issue record not found.');$days=max(0,(int)((new DateTime($issue['due_date']))->diff(new DateTime())->format('%r%a')));$fine=$days*FINE_PER_DAY;$pdo->prepare("UPDATE book_issues SET return_date=CURDATE(),status='returned',fine=? WHERE id=?")->execute([$fine,(int)$_POST['id']]);$pdo->prepare('UPDATE books SET available_quantity=available_quantity+1 WHERE id=?')->execute([$issue['book_id']]);$pdo->commit();flash('success','Book returned. Fine: Rs. '.number_format($fine,2));}
  } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Could not complete action: '.$e->getMessage());}
  redirect('app.php?page='.urlencode($_POST['return_page']??$page));
}

$titles=['dashboard'=>'Dashboard','books'=>'Book Management','categories'=>'Categories','members'=>'Member Management','issues'=>'Issue Books','return'=>'Return Books','overdue'=>'Overdue Books','reports'=>'Reports','users'=>'User Management'];
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
function post_button(string $action,int $id,string $label,string $returnPage,string $class='btn danger'):string{return '<form method="post" class="inline-form" onsubmit="return confirm(\'Are you sure?\')"><input type="hidden" name="csrf" value="'.csrf_token().'"><input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="return_page" value="'.$returnPage.'"><button class="'.$class.'">'.$label.'</button></form>';}
?>
