$stats=['Total Books'=>$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM books')->fetchColumn(),'Available Books'=>$pdo->query('SELECT COALESCE(SUM(available_quantity),0) FROM books')->fetchColumn(),'Issued Books'=>$pdo->query("SELECT COUNT(*) FROM book_issues WHERE return_date IS NULL")->fetchColumn(),'Members'=>$pdo->query('SELECT COUNT(*) FROM members')->fetchColumn()];
