<?php function table_issues(array $rows):void{?><div class="table-wrap"><table><thead><tr><th>Member</th><th>Book</th><th>Issue date</th><th>Due date</th><th>Return date</th><th>Status</th><th>Fine</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No records found.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><strong><?=e($r['title'])?></strong></td><td><?=$r['issue_date']?></td><td><?=$r['due_date']?></td><td><?=$r['return_date']?:'—'?></td><td><span class="badge <?=$r['status']==='returned'?'green':($r['status']==='overdue'?'red':'amber')?>"><?=e($r['status'])?></span></td><td>Rs. <?=number_format((float)$r['fine'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php }
